// friday13.cs — Friday the 13th explorer (proleptic Gregorian calendar)

// 1. Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start on the 13th of Jan 0001
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// 2. Count Friday the 13ths in a full 400-year Gregorian cycle (0001–0400)
int count = 0;
var dayOfWeekCounts = new int[7];

for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        dayOfWeekCounts[(int)d.DayOfWeek]++;
        if (d.DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"\nFriday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Total 13ths checked: {400 * 12}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

Console.WriteLine("\n13th-of-month distribution by day of week:");
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-10} {dayOfWeekCounts[(int)dow],4}");

